package alphametics

import "testing"

func TestEdge(t *testing.T) {
	cases := []struct {
		p    string
		want bool // true if solvable
	}{
		{"SEND + MORE == MONEY", true},
		{"A == B", false},
		{"ACA + DD == BD", false},
		{"I + BB == ILL", true},
		{"A + A == B", true},
		{"AB + AB == CC", false},
		{"AA + AA == BB", false},
		{"THIS + IS == TEST", true},
		{"ZERO + ZERO == ONE", false},
		{"A == A", true},
	}
	for _, c := range cases {
		got, err := Solve(c.p)
		if (err == nil) != c.want {
			t.Fatalf("%q: solvable=%v err=%v sol=%v", c.p, c.want, err, got)
		}
		if err == nil {
			t.Logf("%q -> %v", c.p, got)
		}
	}
	// run twice to ensure no stale global state
	s1, e1 := Solve("SEND + MORE == MONEY")
	s2, e2 := Solve("SEND + MORE == MONEY")
	if e1 != nil || e2 != nil || len(s1) != len(s2) {
		t.Fatalf("repeat call inconsistency: %v %v", e1, e2)
	}
}
